import{_ as t,c as e,o as r,V as a}from"./chunks/framework.B6I5AJO8.js";const y=JSON.parse('{"title":"nb02 · Markdown chunking","description":"","frontmatter":{},"headers":[],"relativePath":"research/markdown-chunking.md","filePath":"research/markdown-chunking.md"}'),n={name:"research/markdown-chunking.md"},i=a('<h1 id="nb02-·-markdown-chunking" tabindex="-1">nb02 · Markdown chunking <a class="header-anchor" href="#nb02-·-markdown-chunking" aria-label="Permalink to &quot;nb02 · Markdown chunking&quot;">​</a></h1><p><strong>Notebook:</strong> <code>notebooks/nb02_markdown_chunking_strategies.ipynb</code> · <strong>Status:</strong> done</p><h2 id="the-question" tabindex="-1">The question <a class="header-anchor" href="#the-question" aria-label="Permalink to &quot;The question&quot;">​</a></h2><p>Markdown is the bulk of the docs. How should it be split so a <strong>code-generation agent</strong> gets enough, intact context? Three design principles drove everything:</p><ul><li><strong>Code-block integrity</strong> — a truncated code example is worse than a missing one: the agent receives an incomplete snippet and completes it incorrectly.</li><li><strong>Heading context</strong> — the position of a chunk in the <code>h1 &gt; h2 &gt; h3</code> hierarchy helps the agent produce correct imports and API calls.</li><li><strong>Context sufficiency over raw relevance</strong> — the relevant criterion is whether a retrieved chunk contains enough (signature + parameters + example) to generate correct code, not topical similarity alone.</li></ul><h2 id="step-1-—-splitter-panorama" tabindex="-1">Step 1 — Splitter panorama <a class="header-anchor" href="#step-1-—-splitter-panorama" aria-label="Permalink to &quot;Step 1 — Splitter panorama&quot;">​</a></h2><p>Five LangChain Markdown splitters were demonstrated on a representative API page and scored on four axes:</p><table><thead><tr><th>Splitter</th><th>Principle</th><th style="text-align:center;">Controls size</th><th style="text-align:center;">Preserves structure</th><th style="text-align:center;">Code integrity</th><th style="text-align:center;">Heading metadata</th></tr></thead><tbody><tr><td>RCT</td><td>character-based recursive</td><td style="text-align:center;">yes</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td><td style="text-align:center;">no</td></tr><tr><td>MHS</td><td>split on headings</td><td style="text-align:center;">no</td><td style="text-align:center;">yes (sections)</td><td style="text-align:center;">depends on section size</td><td style="text-align:center;">yes</td></tr><tr><td>MTS</td><td>Markdown-aware separators</td><td style="text-align:center;">yes</td><td style="text-align:center;">partial</td><td style="text-align:center;">partial</td><td style="text-align:center;">no</td></tr><tr><td>EMSTS</td><td>Markdown AST parsing</td><td style="text-align:center;">no (atoms)</td><td style="text-align:center;"><strong>yes (perfect)</strong></td><td style="text-align:center;"><strong>yes (perfect)</strong></td><td style="text-align:center;">yes (rich)</td></tr></tbody></table><p>No single splitter satisfies all four criteria. EMSTS never breaks a code block or table but emits one atom per element (too granular for retrieval). The selected approach combines <strong>EMSTS parsing + merging adjacent atoms + a heading breadcrumb</strong>.</p><h2 id="step-2-—-four-candidate-strategies" tabindex="-1">Step 2 — Four candidate strategies <a class="header-anchor" href="#step-2-—-four-candidate-strategies" aria-label="Permalink to &quot;Step 2 — Four candidate strategies&quot;">​</a></h2><table><thead><tr><th>ID</th><th>Strategy</th><th>Idea</th></tr></thead><tbody><tr><td>A</td><td>RCT baseline</td><td>recursive character split with heading-aware separators</td></tr><tr><td>B</td><td>MHS + RCT</td><td>header split → RCT re-split; heading hierarchy kept in the payload</td></tr><tr><td>C</td><td>AST-Merge</td><td>EMSTS atoms merged under the same heading up to size — code blocks never split</td></tr><tr><td>D</td><td>AST-Merge + Breadcrumb</td><td>C, plus a <code>Context: h1 &gt; h2 &gt; h3</code> prefix injected into the chunk text</td></tr></tbody></table><h2 id="step-3-—-how-they-were-evaluated" tabindex="-1">Step 3 — How they were evaluated <a class="header-anchor" href="#step-3-—-how-they-were-evaluated" aria-label="Permalink to &quot;Step 3 — How they were evaluated&quot;">​</a></h2><p>Each strategy chunked all of <code>kdk/docs</code> into its own Qdrant collection, then was scored with <strong>deterministic, source-level metrics</strong> (not an LLM-judge-per-chunk rubric):</p><ul><li><strong>recall@5 / hit@5</strong> — are the gold source files in the Top-5?</li><li><strong>code_integrity</strong> — fraction of retrieved chunks with balanced <code>```</code> fences.</li><li><strong>bundle_efficiency</strong> — on-topic chars ÷ total chars in the concatenated Top-K bundle (the agent reads the whole bundle, so wasted chars are wasted context).</li></ul><p>The query set is <strong>439 queries auto-mined from the docs</strong> — each a page title, section heading, or API symbol, with its source file(s) as ground truth (112 title / 266 symbol / 61 section). This replaced an earlier 46-question FAQ set whose ground-truth sources were empty.</p><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h2><table><thead><tr><th>Metric</th><th style="text-align:right;">A (RCT)</th><th style="text-align:right;">B (MHS+RCT)</th><th style="text-align:right;">C (AST-Merge)</th><th style="text-align:right;">D (AST+Breadcrumb)</th></tr></thead><tbody><tr><td>Recall@5</td><td style="text-align:right;">0.862</td><td style="text-align:right;">0.869</td><td style="text-align:right;">0.860</td><td style="text-align:right;">0.867</td></tr><tr><td>Hit@5</td><td style="text-align:right;">0.902</td><td style="text-align:right;">0.909</td><td style="text-align:right;">0.893</td><td style="text-align:right;">0.902</td></tr><tr><td>Code integrity</td><td style="text-align:right;">0.984</td><td style="text-align:right;">0.954</td><td style="text-align:right;"><strong>1.000</strong></td><td style="text-align:right;"><strong>1.000</strong></td></tr><tr><td>Bundle efficiency</td><td style="text-align:right;">0.070</td><td style="text-align:right;">0.112</td><td style="text-align:right;">0.121</td><td style="text-align:right;"><strong>0.142</strong></td></tr></tbody></table><ul><li><strong>Recall is effectively equal</strong> — all four are within ~1 pp (~0.86). File-level retrievability does not distinguish the strategies on this corpus.</li><li><strong>Code integrity is a strict requirement</strong> — character-based A/B leave 2–5% of chunks with unbalanced code fences; AST-based C/D reach <strong>100%</strong>. For a code agent, a chunk with an unbalanced fence is worse than a missing chunk.</li><li><strong>Bundle efficiency is the distinguishing metric</strong> — strategy D&#39;s breadcrumb approximately <strong>doubles</strong> on-topic density relative to A (0.142 vs 0.070), so approximately twice as much relevant documentation fits the same context budget.</li><li><strong>Symbol queries are the most strategy-sensitive</strong> — this is the query form an agent uses when looking up a specific API.</li></ul><p><strong>Known tradeoff:</strong> on bare-symbol lookups, A/B score ~0.857 recall vs D&#39;s 0.820 — the breadcrumb slightly reduces symbol-level embedding similarity. In practice an agent&#39;s query is closer to &quot;how to use <code>&lt;symbol&gt;</code> in <code>&lt;context&gt;</code>&quot;, where the breadcrumb is beneficial rather than detrimental.</p><h2 id="parameter-sweep-on-the-selected-strategy" tabindex="-1">Parameter sweep on the selected strategy <a class="header-anchor" href="#parameter-sweep-on-the-selected-strategy" aria-label="Permalink to &quot;Parameter sweep on the selected strategy&quot;">​</a></h2><p>Varying <code>chunk_size</code> on strategy D:</p><table><thead><tr><th style="text-align:right;">chunk_size</th><th style="text-align:right;">Recall@5</th><th style="text-align:right;">Integrity</th><th style="text-align:right;">Bundle eff.</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>500</strong></td><td style="text-align:right;"><strong>0.877</strong></td><td style="text-align:right;"><strong>1.000</strong></td><td style="text-align:right;"><strong>0.147</strong></td></tr><tr><td style="text-align:right;">1000</td><td style="text-align:right;">0.867</td><td style="text-align:right;">1.000</td><td style="text-align:right;">0.142</td></tr><tr><td style="text-align:right;">1500</td><td style="text-align:right;">0.869</td><td style="text-align:right;">1.000</td><td style="text-align:right;">0.141</td></tr></tbody></table><p><code>chunk_size = 500</code> scores highest on all three: smaller chunks produce finer-grained sections, so the Top-5 bundle contains less off-topic content.</p><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to &quot;Verdict&quot;">​</a></h2><p><strong>Strategy D — AST-Merge + Breadcrumb, <code>chunk_size = 500</code>.</strong> It scores highest on the metrics relevant to code generation (100% integrity, best bundle efficiency) and is approximately equal to the others on recall. This is the Markdown chunker in the <a href="/knowledge/architecture/ingestion-pipeline.html">ingestion pipeline</a>.</p><h2 id="beyond-retrieval-a-code-generation-check" tabindex="-1">Beyond retrieval: a code-generation check <a class="header-anchor" href="#beyond-retrieval-a-code-generation-check" aria-label="Permalink to &quot;Beyond retrieval: a code-generation check&quot;">​</a></h2><p>Deterministic metrics measure retrieval quality, but the real product question is whether an agent fed only the Top-K bundle writes correct Kalisio code. Five Kalisio coding tasks were run through all four strategies; qualitative review found that D&#39;s breadcrumb tags (e.g. <code>Context: Globe Mixins &gt; Methods &gt; setStyle</code>) provide clearer hierarchical context than A&#39;s raw fragments, which sometimes include unrelated API surface from the same file.</p>',27),s=[i];function o(d,l,h,c,g,u){return r(),e("div",null,s)}const m=t(n,[["render",o]]);export{y as __pageData,m as default};
